 const activityToggle=useRef();
 useEffect(()=>{try{localStorage.setItem(ACTIVITY_VISIBLE_KEY,String(activityVisible));}catch{/* The panel still works when browser storage is unavailable. */}},[activityVisible]);
 useEffect(()=>{try{localStorage.setItem(EMOTION_ANIMATION_KEY,String(emotionAnimation));}catch{/* The setting still works for this session. */}},[emotionAnimation]);
 useEffect(()=>{try{localStorage.setItem(SKILL_ANIMATION_KEY,String(skillAnimation));}catch{/* The setting still works for this session. */}},[skillAnimation]);
 useEffect(()=>{const query=window.matchMedia?.('(prefers-reduced-motion: reduce)');if(!query)return;const update=event=>setReducedMotion(event.matches);query.addEventListener?.('change',update);return()=>query.removeEventListener?.('change',update);},[]);
 useEffect(()=>{
 const fresh=(game.emotionHistory||game.emotionEvents||[]).filter(event=>event.id>processedEmotionSequence.current);
  if(!fresh.length){suppressSkillEmotions.current=false;return;}
  processedEmotionSequence.current=Math.max(processedEmotionSequence.current,...fresh.map(event=>event.id));
  const visibleFresh=fresh.filter(event=>!(suppressSkillEmotions.current&&event.category?.startsWith('skill')));
  if(visibleFresh.length)setEmotionQueue(current=>[...current,...visibleFresh].sort((a,b)=>b.priority-a.priority||a.id-b.id).slice(0,3));
  suppressSkillEmotions.current=false;
 },[game.emotionEvents]);
 useEffect(()=>{
  if(!activeEmotion||modal||(game.stage==='moving'&&activeEmotion.priority<90))return;
  const id=activeEmotion.id;
  const timer=setTimeout(()=>setEmotionQueue(current=>current[0]?.id===id?current.slice(1):current.filter(event=>event.id!==id)),2400);
  return()=>clearTimeout(timer);
 },[activeEmotion?.id,game.stage,modal]);
 useEffect(()=>{const latest=game.log[0];if(latest?.kind!=='skill'){lastSkillLog.current=latest?.text||'';return;}if(latest.text===lastSkillLog.current)return;lastSkillLog.current=latest.text;if(!skillAnimation||reducedMotion)return;setSkillPulse(true);const timer=setTimeout(()=>setSkillPulse(false),720);return()=>clearTimeout(timer);},[game.log,skillAnimation,reducedMotion]);
 const saveGlassOpacity=e=>{const value=clampGlassOpacity(Number(e.currentTarget.value));setGlassOpacity(value);try{localStorage.setItem(GLASS_OPACITY_KEY,String(value));}catch{/* The visual setting still works when browser storage is unavailable. */}};
 const [selected,setSelected]=useState(null),[tab,setTab]=useState('players'),[playerStatusId,setPlayerStatusId]=useState(null),[skillSelectedId,setSkillSelectedId]=useState(null),[skillDraft,setSkillDraft]=useState(null),[skillSequence,setSkillSequence]=useState(null),[sound,setSound]=useState(false),[rotating,setRotating]=useState(false),[error,setError]=useState(''),[saveError,setSaveError]=useState(false),[setup,setSetup]=useState({count:4,roundOption:'40',customRounds:'100',inflationRate:DEFAULT_INFLATION_RATE,limitBuildings:true,players:[{name:'你',color:COLORS[0],human:true},{name:'艾米',color:COLORS[1],human:false},{name:'小傑',color:COLORS[2],human:false},{name:'喵喵',color:COLORS[3],human:false}]});
 const board=useRef(),audio=useRef();const player=game.players[game.turn],human=!!player?.human&&!player?.bankrupt;const active=human&&['ready','end'].includes(game.stage);
 const roll=()=>{dispatch({type:'ROLL',dice:Array.from({length:player.diceCount??2},()=>1+Math.floor(Math.random()*6)),eventIndex:Math.floor(Math.random()*8)});};
 const aiSkillAction=()=>{if(!player||player.skillUsedThisTurn||game.pendingSkill||game.skillOverflow)return null;const opponents=game.players.filter(candidate=>candidate.id!==player.id&&!candidate.bankrupt);const target=opponents[0];const slowTarget=opponents.find(candidate=>candidate.slowTurns===0);const own=ownLots(game,player.id),opponentLot=TILES.find(tile=>tile.type==='property'&&game.lots[tile.id]?.owner!==undefined&&game.lots[tile.id].owner!==player.id&&!game.players[game.lots[tile.id].owner]?.bankrupt);const hand=player.skillHand;const has=id=>hand.includes(id);const pick=action=>canUseSkillCard(game,action)?action:null;if(player.cash<7000&&has('subsidy'))return pick({type:'USE_SKILL_CARD',cardId:'subsidy'});if(player.cash<9000&&has('rent-shield'))return pick({type:'USE_SKILL_CARD',cardId:'rent-shield'});if(player.jail&&has('get-out'))return pick({type:'USE_SKILL_CARD',cardId:'get-out'});if(slowTarget&&has('slow'))return pick({type:'USE_SKILL_CARD',cardId:'slow',targetId:slowTarget.id});if(opponents.length&&has('trap'))return pick({type:'USE_SKILL_CARD',cardId:'trap',targetId:target.id});if(opponents.length&&has('teleport')){const destination=LEGAL_TELEPORT_POSITIONS.find(id=>id!==target.pos&&TILES[id].type==='property')??0;return pick({type:'USE_SKILL_CARD',cardId:'teleport',targetId:target.id,targetPosition:destination});}if(opponents.length&&has('position-swap'))return pick({type:'USE_SKILL_CARD',cardId:'position-swap',targetId:target.id});if(own.length&&has('rent-double'))return pick({type:'USE_SKILL_CARD',cardId:'rent-double'});if(own.length&&opponentLot&&has('land-swap'))return pick({type:'USE_SKILL_CARD',cardId:'land-swap',ownLotId:own[0].id,targetLotId:opponentLot.id});if(has('birthday')&&opponents.length)return pick({type:'USE_SKILL_CARD',cardId:'birthday'});return null;};
 useEffect(()=>{try{listSaves();}catch{setSaveError(true);}},[]);
 useEffect(()=>{if(screen!=='game'||game.stage==='moving')return;try{saveAuto(game);setSaveError(false);}catch{setSaveError(true);}},[game,screen]);
 useEffect(()=>{if(game.stage==='moving'&&modal!=='saves'){const timer=setTimeout(()=>dispatch({type:'STEP'}),330);return()=>clearTimeout(timer);}},[game,modal]);
 useEffect(()=>{
  const landedId=game.selected;
  const landedTile=landedId===null?null:TILES[landedId];
  const landedLot=landedId===null?null:game.lots[landedId];
  const shouldOpenPurchase=human&&game.stage==='decision'&&landedTile?.type==='property'&&!landedLot;
  const shouldOpenBuild=human&&game.stage==='end'&&game.buildAvailable&&landedLot?.owner===game.turn;
  if(shouldOpenPurchase||shouldOpenBuild){
   setSelected(landedId);
   setModal('property');
  }
 },[game,human]);
 useEffect(()=>{if(screen!=='game'||human||game.stage==='finished'||game.pendingSkill||skillSequence||modal==='new'||modal==='rules'||modal==='saves')return;const timer=setTimeout(()=>{if(game.stage==='ready'){const skill=aiSkillAction();if(skill)startSkillSequence(skill);else roll();}else if(game.stage==='decision')dispatch({type:player.cash>propertyPrice(game,TILES[player.pos])+inflationAmount(game,1800)?'BUY':'SKIP'});else if(game.stage==='end'){const t=ownLots(game,game.turn).find(t=>canBuild(game,t.id)&&player.cash>buildCost(t,game)+inflationAmount(game,2500));if(t)dispatch({type:'BUILD',id:t.id});else dispatch({type:'NEXT'});}},game.stage==='decision'?1300:1100);return()=>clearTimeout(timer);},[game,human,modal,screen,skillSequence]);
 useEffect(()=>{const overflow=game.skillOverflow;if(!overflow)return;const holder=game.players[overflow.playerId];if(holder?.human||!holder?.skillHand?.length)return;const discardId=holder.skillHand.at(-1);const timer=setTimeout(()=>dispatch({type:'RESOLVE_SKILL_OVERFLOW',cardId:discardId}),350);return()=>clearTimeout(timer);},[game.skillOverflow?.playerId,game.players,game.skillOverflow]);
 useEffect(()=>{const pending=game.pendingSkill;if(!pending)return;const target=game.players[pending.targetId];if(target?.human)return;const response=target?.skillHand.includes('counter')?'counter':target?.skillHand.includes('reflect')?'reflect':'pass';const timer=setTimeout(()=>dispatch({type:'RESPOND_SKILL',playerId:pending.targetId,response}),520);return()=>clearTimeout(timer);},[game.pendingSkill?.sourceId,game.pendingSkill?.targetId,game.pendingSkill?.cardId,game.players]);
 useEffect(()=>{if(!sound||!audio.current)return;try{const ctx=audio.current,o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type='sine';o.frequency.setValueAtTime(game.stage==='moving'?380:620,ctx.currentTime);g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.13);o.start();o.stop(ctx.currentTime+.15);}catch{}},[game.remaining,game.stage,sound]);
 const toggleSound=()=>{if(!sound){const A=window.AudioContext||window.webkitAudioContext;if(A){audio.current ||= new A();audio.current.resume();}}setSound(!sound);};
 const inspect=id=>{setSelected(id);setModal('property');};
 const newGameMaxRounds=parseRoundLimit(setup);
 const openNewGame=()=>setModal('new');
 const goHome=()=>{setModal(null);try{setContinueGame(readAuto());}catch{setContinueGame(null);}setScreen('home');};
 const startNew=()=>{if(setup.roundOption==='custom'&&!newGameMaxRounds)return;setEmotionQueue([]);processedEmotionSequence.current=0;dispatch({type:'NEW',config:{...setup,maxRounds:newGameMaxRounds,inflationRate:Number(setup.inflationRate)}});setScreen('game');setModal(null);setPlayerStatusId(null);setTab('players');board.current?.reset();setRotating(false);};
 const continueProgress=()=>{if(!continueGame)return;setEmotionQueue([]);processedEmotionSequence.current=0;dispatch({type:'LOAD',game:continueGame});setScreen('game');setModal(null);setSelected(null);setPlayerStatusId(null);setTab('players');};
 const newGameModal=modal==='new'?<NewGameSetupModal setup={setup} setSetup={setSetup} newGameMaxRounds={newGameMaxRounds} onStart={startNew} onClose={()=>setModal(null)}/>:null;
 if(screen==='home')return <div className="app-shell home-shell"><HomeScreen hasContinue={!!continueGame} onNewGame={openNewGame} onContinue={continueProgress}/>{newGameModal}</div>;
 const t=selected!==null?TILES[selected]:null,l=t?game.lots[t.id]:null;const landed=TILES[player.pos];
