 const skillCardDisabled=card=>!skillReady||card.timing!=='active'||!SUPPORTED_ACTIVE_SKILLS.has(card.id)||(card.id==='get-out'&&!player.jail)||(card.id==='slow'&&!slowTargetPlayers.length)||(card.id==='rent-double'&&(!ownSkillLots.length||player.rentMultiplier===2))||(card.id==='rent-shield'&&player.rentShield===1)||(card.id==='birthday'&&!targetPlayers.length);
 const immediateSkillDisabled=card=>!overflowPlayer?.human||game.skillOverflow?.playerId!==game.turn||game.pendingSkill||skillSequence||player.skillUsedThisTurn||card.timing!=='active'||!SUPPORTED_ACTIVE_SKILLS.has(card.id)||(card.id==='get-out'&&!player.jail)||(card.id==='slow'&&!slowTargetPlayers.length)||(card.id==='rent-double'&&(!ownSkillLots.length||player.rentMultiplier===2))||(card.id==='rent-shield'&&player.rentShield===1)||(card.id==='birthday'&&!targetPlayers.length)||(card.target==='player'&&card.id!=='slow'&&!targetPlayers.length)||(card.target==='land'&&(!ownSkillLots.length||!opponentSkillLots.length));
